-- V2 is additive. Older clients keep merge_account_quiz_state and quiz_state reads.
-- All writes, including those older paths and direct table upserts, acquire the
-- same account transaction lock before assigning a transactional cursor.
create schema quiz_sync_private;
revoke all on schema quiz_sync_private from public, anon, authenticated;
grant usage on schema quiz_sync_private to authenticated;

alter table quiz_pk_private.questions
  add column canonical_question_id text,
  add column answerable boolean not null default false,
  add column practice_options text[] not null default '{}',
  add column practice_correct_options text[] not null default '{}',
  add column catalog_version text,
  add column live_enabled boolean not null default false,
  add column arena_enabled boolean not null default false;
update quiz_pk_private.questions set live_enabled = correct_options is not null,
  arena_enabled = options is not null;

create table quiz_sync_private.question_versions (
  catalog_version text not null,
  question_id text not null,
  canonical_question_id text not null,
  chapter text not null,
  question_type text not null,
  answerable boolean not null,
  options text[] not null,
  correct_options text[] not null,
  primary key (catalog_version, question_id)
);

-- Generated from content/questions.json; SHA-256 d8554f735f0c58a524049ee72b4b77f004bc3b40a5726bb5a975d48d07db5e08.
-- Existing online-game options remain unchanged; practice grading has its own complete catalog.
on conflict(question_id) do update set
  canonical_question_id=excluded.canonical_question_id,chapter=excluded.chapter,question_type=excluded.question_type,
  live_enabled=current.live_enabled and (current.catalog_version is null or (current.practice_options=excluded.practice_options and current.practice_correct_options=excluded.practice_correct_options)),
  arena_enabled=current.arena_enabled and (current.catalog_version is null or (current.practice_options=excluded.practice_options and current.practice_correct_options=excluded.practice_correct_options)),
  answerable=excluded.answerable,practice_options=excluded.practice_options,practice_correct_options=excluded.practice_correct_options,
  catalog_version=excluded.catalog_version;
-- Retire removed questions without deleting versions referenced by attempts or games.
update quiz_pk_private.questions set answerable=false,live_enabled=false,arena_enabled=false
where catalog_version is distinct from 'd8554f735f0c58a524049ee72b4b77f004bc3b40a5726bb5a975d48d07db5e08';
  select catalog_version,question_id,canonical_question_id,chapter,question_type,answerable,practice_options,practice_correct_options
  from quiz_pk_private.questions where catalog_version='d8554f735f0c58a524049ee72b4b77f004bc3b40a5726bb5a975d48d07db5e08'
  on conflict(catalog_version,question_id) do nothing;

alter table quiz_pk_private.questions
  alter column canonical_question_id set not null,
  alter column catalog_version set not null,
  add foreign key (canonical_question_id) references quiz_pk_private.questions(question_id);


alter table public.quiz_state add column sync_cursor bigint not null default 0;
alter table public.quiz_state
  drop constraint quiz_state_kind_check,
  drop constraint quiz_state_check,
  add constraint quiz_state_kind_check check (kind in ('history','star','session','note','draft','test')),
  add constraint quiz_state_check check (
    octet_length(payload::text) <= 240000 and (
      (kind = 'star' and jsonb_typeof(payload) = 'boolean') or
      (kind in ('history','session','test') and jsonb_typeof(payload) = 'object') or
      (kind = 'draft' and jsonb_typeof(payload) in ('object','null')) or
      (kind = 'note' and jsonb_typeof(payload) = 'string' and char_length(payload #>> '{}') <= 8000)
    )
  );
create index quiz_state_incremental on public.quiz_state (account_id, sync_cursor);

create table quiz_sync_private.clocks (
  account_id uuid primary key references public.quiz_members(account_id) on delete cascade,
  last_cursor bigint not null default 0 check (last_cursor between 0 and 9007199254740991)
);
create table quiz_sync_private.tombstones (
  account_id uuid not null references public.quiz_members(account_id) on delete cascade,
  kind text not null,
  record_key text not null,
  revision bigint not null,
  change_id uuid not null,
  sync_cursor bigint not null,
  primary key (account_id, kind, record_key)
);
create index quiz_tombstones_incremental on quiz_sync_private.tombstones (account_id, sync_cursor);

create table quiz_sync_private.attempts (
  account_id uuid not null references public.quiz_members(account_id) on delete cascade,
  event_id uuid not null,
  question_id text not null,
  canonical_question_id text not null,
  selected text[] not null,
  correct boolean not null,
  occurred_at bigint not null check (occurred_at between 1 and 9999999999999),
  received_at timestamptz not null default statement_timestamp(),
  mode text not null check (mode in ('practice','chapter-test','review')),
  catalog_version text not null,
  source text not null default 'v2' check (source in ('v2','legacy_sync','legacy_snapshot')),
  sync_cursor bigint not null,
  primary key (account_id, event_id),
  foreign key (catalog_version, question_id)
    references quiz_sync_private.question_versions(catalog_version, question_id)
);
create index quiz_attempts_incremental on quiz_sync_private.attempts (account_id, sync_cursor);
create index quiz_attempts_daily on quiz_sync_private.attempts (account_id, occurred_at);
alter table quiz_sync_private.question_versions enable row level security;
alter table quiz_sync_private.clocks enable row level security;
alter table quiz_sync_private.tombstones enable row level security;
alter table quiz_sync_private.attempts enable row level security;
revoke all on all tables in schema quiz_sync_private from public, anon, authenticated;

create function quiz_sync_private.lock_account(account uuid)
returns void language sql set search_path = '' as $$
  select pg_advisory_xact_lock(hashtextextended('quiz_sync_v2:' || account::text, 0))
$$;
create function quiz_sync_private.next_cursor(account uuid)
returns bigint language plpgsql set search_path = '' as $$
declare next_value bigint;
begin
  perform quiz_sync_private.lock_account(account);
  on conflict (account_id) do update set last_cursor = previous.last_cursor + 1
  returning last_cursor into next_value;
  return next_value;
end;
$$;

create function quiz_sync_private.stamp_state()
returns trigger language plpgsql security definer set search_path = '' as $$
declare removed quiz_sync_private.tombstones;
begin
  if tg_op = 'UPDATE' and (new.account_id, new.kind, new.record_key) is distinct from
    (old.account_id, old.kind, old.record_key) then
    raise exception 'quiz_state_identity_is_immutable' using errcode = '22023';
  end if;
  perform quiz_sync_private.lock_account(new.account_id);
  if tg_op = 'UPDATE' and old.sync_cursor > 0 and
    (new.revision, new.change_id, new.payload) is not distinct from (old.revision, old.change_id, old.payload) then
    new.sync_cursor := old.sync_cursor;
    return new;
  end if;
  select * into removed from quiz_sync_private.tombstones
    where account_id = new.account_id and kind = new.kind and record_key = new.record_key;
  if found and (new.revision, new.change_id) <= (removed.revision, removed.change_id) then
    return null;
  end if;
  new.sync_cursor := quiz_sync_private.next_cursor(new.account_id);
  delete from quiz_sync_private.tombstones
    where account_id = new.account_id and kind = new.kind and record_key = new.record_key;
  return new;
end;
$$;
create trigger quiz_sync_stamp_state before insert or update on public.quiz_state
  for each row execute function quiz_sync_private.stamp_state();

create function quiz_sync_private.delete_state()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  -- Account deletion cascades have no remaining client or cursor to notify.
  if not exists (select 1 from public.quiz_members where account_id = old.account_id) then return old; end if;
  perform quiz_sync_private.lock_account(old.account_id);
  values (old.account_id, old.kind, old.record_key, least(9999999999999, old.revision + 1),
    gen_random_uuid(), quiz_sync_private.next_cursor(old.account_id))
  on conflict (account_id, kind, record_key) do update
  set revision = excluded.revision, change_id = excluded.change_id, sync_cursor = excluded.sync_cursor;
  return old;
end;
$$;
create trigger quiz_sync_delete_state before delete on public.quiz_state
  for each row execute function quiz_sync_private.delete_state();

create function quiz_sync_private.stamp_attempt()
returns trigger language plpgsql set search_path = '' as $$
begin
  new.sync_cursor := quiz_sync_private.next_cursor(new.account_id);
  new.received_at := statement_timestamp();
  return new;
end;
$$;
create trigger quiz_sync_stamp_attempt before insert on quiz_sync_private.attempts
  for each row execute function quiz_sync_private.stamp_attempt();

create function quiz_sync_private.selection(value jsonb)
returns text[] language sql immutable set search_path = '' as $$
  select coalesce(array_agg(item #>> '{}' order by item #>> '{}'), '{}'::text[])
  from jsonb_array_elements(case when jsonb_typeof(value) = 'array' then value else '[]'::jsonb end) item
  where jsonb_typeof(item) = 'string'
$$;

create function quiz_sync_private.capture_legacy_attempt()
returns trigger language plpgsql security definer set search_path = '' as $$
declare question quiz_pk_private.questions;
begin
  if new.kind <> 'history' or current_setting('quiz.sync_v2', true) = 'on' then return new; end if;
  if tg_op = 'UPDATE' and (new.payload->'last', new.payload->'selected', new.payload->'wrong') is not distinct from
    (old.payload->'last', old.payload->'selected', old.payload->'wrong') then return new; end if;
  if jsonb_typeof(new.payload->'wrong') is distinct from 'boolean' or
    coalesce(new.payload->>'last','') !~ '^[0-9]{1,13}$' then return new; end if;
  if (new.payload->>'last')::bigint < 1 then return new; end if;
  select * into question from quiz_pk_private.questions where question_id = new.record_key and answerable;
  if not found then return new; end if;
  values (new.account_id,new.change_id,new.record_key,question.canonical_question_id,
    quiz_sync_private.selection(new.payload->'selected'), new.payload->'wrong' = 'false'::jsonb,
    (new.payload->>'last')::bigint,'practice',question.catalog_version,'legacy_sync',0)
  on conflict (account_id,event_id) do nothing;
  return new;
end;
$$;
create trigger quiz_sync_capture_legacy after insert or update on public.quiz_state
  for each row execute function quiz_sync_private.capture_legacy_attempt();

-- Give pre-v2 rows positive cursors. This does not manufacture repeated attempts.
update public.quiz_state set sync_cursor = 0;
select account_id, md5('legacy-snapshot:' || account_id::text || ':' || canonical_question_id)::uuid,
  record_key,canonical_question_id,quiz_sync_private.selection(payload->'selected'),payload->'wrong' = 'false'::jsonb,
  (payload->>'last')::bigint,'practice',catalog_version,'legacy_snapshot',0
from (
  select distinct on (s.account_id,q.canonical_question_id) s.*,q.canonical_question_id,q.catalog_version
  from public.quiz_state s join quiz_pk_private.questions q on q.question_id = s.record_key and q.answerable
  where s.kind='history' and jsonb_typeof(s.payload->'wrong')='boolean'
    and case when s.payload->>'last' ~ '^[0-9]{1,13}$' then (s.payload->>'last')::bigint > 0 else false end
  order by s.account_id,q.canonical_question_id,(s.payload->>'last')::bigint desc,s.revision desc,s.change_id desc
) known on conflict (account_id,event_id) do nothing;

-- Preserve an explicit JSON null draft tombstone; recordset conversion would
-- coerce it to SQL NULL and reject the complete answer transaction.
create or replace function public.merge_account_quiz_state(expected_account uuid, changes jsonb)
returns void
language plpgsql
security invoker
set search_path = ''
as $$
declare
  actor uuid := (select auth.uid());
begin
  if actor is null or actor is distinct from expected_account or not exists (select 1 from public.quiz_members where account_id = actor) then
    raise exception 'account not enrolled' using errcode = '42501';
  end if;
  if jsonb_typeof(changes) is distinct from 'array'
    or jsonb_array_length(changes) > 100
    or octet_length(changes::text) > 350000 then
    raise exception 'invalid changes' using errcode = '22023';
  end if;

  -- Same lock as v2; acquire before row locks in this supported write path.
  perform pg_advisory_xact_lock(hashtextextended('quiz_sync_v2:' || actor::text, 0));

    select actor, entry.kind, entry.record_key, entry.revision, entry.change_id, input.value->'payload'
    from jsonb_array_elements(changes) input(value)
    cross join lateral jsonb_to_record(input.value) as entry(
      kind text, record_key text, revision bigint, change_id uuid
    )
    on conflict (account_id, kind, record_key) do update
    set revision = excluded.revision, change_id = excluded.change_id, payload = excluded.payload
    where (excluded.revision, excluded.change_id) > (old.revision, old.change_id);
end;
$$;

create function quiz_sync_private.sync_v2(expected_account uuid, changes jsonb, attempts jsonb, cursor bigint, page_size integer)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  actor uuid := auth.uid();
  event record;
  question quiz_sync_private.question_versions;
  previous quiz_sync_private.attempts;
  picks text[];
  version text;
  old_flag text := current_setting('quiz.sync_v2', true);
  watermark bigint;
  response jsonb;
begin
  if actor is null or actor is distinct from expected_account or not exists
    (select 1 from public.quiz_members where account_id=actor) then
    raise exception 'account not enrolled' using errcode='42501';
  end if;
  if cursor is null or cursor < 0 or cursor > 9007199254740991 or page_size is null or page_size not between 1 and 500 then
    raise exception 'quiz_invalid_cursor' using errcode='22023';
  end if;
  if jsonb_typeof(changes) is distinct from 'array' or jsonb_array_length(changes)>100 or octet_length(changes::text)>350000 or
    jsonb_typeof(attempts) is distinct from 'array' or jsonb_array_length(attempts)>100 or octet_length(attempts::text)>100000 then
    raise exception 'quiz_invalid_sync_batch' using errcode='22023';
  end if;
  perform quiz_sync_private.lock_account(actor);
  select coalesce((select last_cursor from quiz_sync_private.clocks where account_id=actor),0) into watermark;
  if cursor > watermark then raise exception 'quiz_cursor_ahead' using errcode='22023'; end if;
  perform set_config('quiz.sync_v2','on',true);

  for event in select * from jsonb_to_recordset(attempts) as input(
    event_id uuid, question_id text, selected jsonb, occurred_at bigint, mode text, catalog_version text
  ) loop
    version := event.catalog_version;
    select * into question from quiz_sync_private.question_versions q
      where q.catalog_version=version and q.question_id=event.question_id and q.answerable;
    if not found then raise exception 'quiz_catalog_unavailable' using errcode='22023'; end if;
    if event.event_id is null or event.occurred_at is null or event.occurred_at not between 1 and 9999999999999 or
      event.mode is null or event.mode not in ('practice','chapter-test','review') or
      jsonb_typeof(event.selected) is distinct from 'array' then
      raise exception 'quiz_invalid_attempt' using errcode='22023';
    end if;
    picks := quiz_sync_private.selection(event.selected);
    if cardinality(picks) <> jsonb_array_length(event.selected) or not (picks <@ question.options) or
      cardinality(picks) <> (select count(distinct pick) from unnest(picks) pick) then
      raise exception 'quiz_invalid_attempt' using errcode='22023';
    end if;
    select * into previous from quiz_sync_private.attempts a where a.account_id=actor and a.event_id=event.event_id;
    if found then
      if (previous.question_id,previous.selected,previous.occurred_at,previous.mode,previous.catalog_version) is distinct from
        (event.question_id,picks,event.occurred_at,event.mode,version) then
        raise exception 'quiz_attempt_conflict' using errcode='22023';
      end if;
    else
      values (actor,event.event_id,event.question_id,question.canonical_question_id,picks,
        picks=question.correct_options,event.occurred_at,event.mode,version,0);
    end if;
  end loop;
  perform public.merge_account_quiz_state(actor,changes);
  perform set_config('quiz.sync_v2',coalesce(old_flag,''),true);
  select coalesce((select last_cursor from quiz_sync_private.clocks where account_id=actor),0) into watermark;

  with candidates as (
    select s.sync_cursor,'state' as category,jsonb_build_object(
      'kind',s.kind,'record_key',s.record_key,'revision',s.revision,'change_id',s.change_id,'payload',s.payload,'sync_cursor',s.sync_cursor
    ) as row from public.quiz_state s where s.account_id=actor and s.sync_cursor>cursor
    union all
    select t.sync_cursor,'state',jsonb_build_object(
      'kind',t.kind,'record_key',t.record_key,'revision',t.revision,'change_id',t.change_id,'payload',null,'deleted',true,'sync_cursor',t.sync_cursor
    ) from quiz_sync_private.tombstones t where t.account_id=actor and t.sync_cursor>cursor
    union all
    select a.sync_cursor,'attempt',jsonb_build_object(
      'event_id',a.event_id,'question_id',a.question_id,'canonical_question_id',a.canonical_question_id,
      'selected',a.selected,'correct',a.correct,'occurred_at',a.occurred_at,'received_at',a.received_at,
      'mode',a.mode,'catalog_version',a.catalog_version,'source',a.source,'sync_cursor',a.sync_cursor
    ) from quiz_sync_private.attempts a where a.account_id=actor and a.sync_cursor>cursor
  ), page as (
    select *,row_number() over (order by sync_cursor) as position from (
      select * from candidates order by sync_cursor limit page_size+1
    ) bounded
  ) select jsonb_build_object(
    'version',2,
    'ack',jsonb_build_object(
      'changes',coalesce((select jsonb_agg(value->'change_id') from jsonb_array_elements(changes)),'[]'::jsonb),
      'attempts',coalesce((select jsonb_agg(value->'event_id') from jsonb_array_elements(attempts)),'[]'::jsonb)),
    'rows',coalesce(jsonb_agg(row order by sync_cursor) filter (where category='state' and position<=page_size),'[]'::jsonb),
    'attemptRows',coalesce(jsonb_agg(row order by sync_cursor) filter (where category='attempt' and position<=page_size),'[]'::jsonb),
    'next_cursor',case when count(*)>page_size then max(sync_cursor) filter (where position<=page_size) else watermark end,
    'has_more',count(*)>page_size,
    'high_watermark',watermark
  ) into response from page;
  return response;
end;
$$;

create function public.quiz_sync_v2(expected_account uuid, changes jsonb default '[]'::jsonb,
  attempts jsonb default '[]'::jsonb, cursor bigint default 0, page_size integer default 200)
returns jsonb language sql security invoker set search_path='' as $$
  select quiz_sync_private.sync_v2(expected_account,changes,attempts,cursor,page_size)
$$;
revoke all on all functions in schema quiz_sync_private from public, anon, authenticated;
grant execute on function quiz_sync_private.sync_v2(uuid,jsonb,jsonb,bigint,integer) to authenticated;
revoke all on function public.quiz_sync_v2(uuid,jsonb,jsonb,bigint,integer) from public, anon, authenticated;
grant execute on function public.quiz_sync_v2(uuid,jsonb,jsonb,bigint,integer) to authenticated;
